cd /workspace/mytests && timeout 900 python3 - <<'EOF'
"""Differential test incl. case flags, with randomised identity mismatches."""
import json, random, sys
sys.path.insert(0,'/workspace/mytests')
from harness import run, doc
import ref_channel as rc
from diff_parse import rand_request

def case_flags(o, rf):
    f=set()
    if rf>0 and o['count']==0: f.add('missing_origin')
    if o['count']>1: f.add('extra_origin')
    if o['count']>0 and rf==0: f.add('unsent_origin')
    if o['identity']: f.add('identity')
    if o['mixed']: f.add('mixed_origin')
    return sorted(f)

bad=0
for seed in range(600):
    rnd = random.Random(seed+9000)
    ncases = rnd.randrange(1,4)
    names=['c%d'%i for i in range(ncases)]
    expects={}; cases=[]; sent_rf={}
    for i,nm in enumerate(names):
        m = rnd.choice(['GET','POST','PUT'])
        t = rnd.choice(['/','/x','/y?z'])
        h = rnd.choice(['h.example','H.EXAMPLE','other.example'])
        expects[nm]={'method':m.encode(),'target':t.encode(),'host_folded':h.lower().encode()}
        frames=[]
        if rnd.random()<0.8:
            frames.append({"Type":"headers","End_Stream":True,
                           "data_to_transfered":[[":method",m],[":path",t],["Host",h]]})
        else:
            frames.append({"Type":"datagram","data_to_transfered":"dg"})
        cases.append({"name":nm,"frames":frames,"expect":{"method":m,"target":t,"host":h}})
    channels=[]; refparts=[]
    for ci in range(rnd.randrange(1,4)):
        parts=[]; rp=[]
        for p in range(rnd.randrange(1,5)):
            blob = rand_request(rnd)
            if all(x<128 for x in blob):
                owner = rnd.choice([None]+names)
                parts.append({"case":owner,"data":blob.decode('latin1')})
                rp.append((owner,blob))
        channels.append({"name":"ch%d"%ci,"parts":parts}); refparts.append(rp)
    events=[{"at":1,"kind":"headers","stream":4*i,"fields":[[":status","200"]],"end":True} for i in range(ncases) if rnd.random()<0.8]
    d=doc(cases=cases, channels=channels, events=events)
    out,code,err=run(d)
    if 'error' in out:
        print('seed',seed,'unexpected error',err[-300:]); bad+=1; continue
    budget={'requests':0,'chunk':0}; seen=set()
    origin={n:{'count':0,'identity':False,'mixed':False} for n in names}
    sent_frames={c['name']:c['request_frames'] for c in out['cases']}
    expected=[]
    for idx,parts in enumerate(refparts):
        rec,origin = rc.channel_record('ch%d'%idx, parts, expects, sent_frames, seen, budget, origin)
        expected.append(rec)
    if out['channels']!=expected:
        bad+=1
        if bad<3:
            print('CH MISMATCH',seed); print(json.dumps(out['channels'])[:900]); print(json.dumps(expected)[:900])
        continue
    for c in out['cases']:
        want = case_flags(origin[c['name']], c['request_frames'])
        if c['flags']!=want or c['origin_count']!=origin[c['name']]['count']:
            bad+=1
            if bad<5: print('FLAG MISMATCH',seed,c['name'],c['flags'],want,c['origin_count'],origin[c['name']])
print('done bad =',bad)
EOF
